import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    t = int(next(iterator))

    results = []

    for _ in range(t):
        n = int(next(iterator))
        m = int(next(iterator))

        a = []
        for _ in range(n):
            a.append(int(next(iterator)))

        k = int(next(iterator))
        b = []
        for _ in range(k):
            b.append(int(next(iterator)))

        def decompose(arr, m_val):
            # Returns a list of tuples: (value, count)
            res = []
            for x in arr:
                if x == 0:
                    continue
                cnt = 1
                while x % m_val == 0:
                    cnt *= m_val
                    x //= m_val
                if res and res[-1][0] == x:
                    res[-1] = (x, res[-1][1] + cnt)
                else:
                    res.append((x, cnt))
            return res

        dec_a = decompose(a, m)
        dec_b = decompose(b, m)

        if len(dec_a) != len(dec_b):
            results.append("No")
            continue

        possible = True
        for i in range(len(dec_a)):
            val_a, cnt_a = dec_a[i]
            val_b, cnt_b = dec_b[i]
            if val_a != val_b or cnt_a < cnt_b:
                possible = False
                break

        if possible:
            results.append("Yes")
        else:
            results.append("No")

    print('\n'.join(results))

if __name__ == '__main__':
    solve()
